-- -----------------------------------
-- Table structure for `alert_assign`
-- -----------------------------------

DROP TABLE IF EXISTS `alert_assign`;
CREATE TABLE `alert_assign` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `alertid` varchar(200) CHARACTER SET utf8 NOT NULL,
  `userAssign` varchar(200) CHARACTER SET utf8 NOT NULL,
  `DataRead` varchar(200) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=156126 DEFAULT CHARSET=latin1;

